// --- Sparse-CBOR write (ADR-0042 driver path). ---

// Marshal writes the SoA buffer to w as the sparse-CBOR wire
// format produced through factsschema/dml_cbor. Thin wrapper
// around ItemBuildEntities — the per-row chain lives there and
// works against any leeway-DML class that structurally satisfies
// ItemEntityI.
func (c *ItemColumns) Marshal(w io.Writer) (err error) {
	ent := itemPool.Get().(*cbdml.InEntityFacts)
	defer itemPool.Put(ent)
	ent.SetActiveSections(ItemActiveSections)
	ent.Builder().SetActiveFields(ItemActiveFields())
	err = ItemBuildEntities(ent, c)
	if err != nil {
		return
	}
	var recs []*arrowrowcbor.Record
	recs, err = ent.TransferRecords(nil)
	if err != nil {
		err = eh.Errorf("stevedoreitem: transfer records: %w", err)
		return
	}
	rb := arrowrowcbor.JoinRecords(recs)
	_, err = w.Write(rb)
	if err != nil {
		err = eh.Errorf("stevedoreitem: marshal write: %w", err)
	}
	return
}

// --- Read path (ra-based). ---

// itemReader composes the readaccess helpers this kind needs.
// Constructed per Unmarshal call; released via defer.
type itemReader struct {
	EntityId        *ra.ReadAccessFactsPlainEntityIdAttributes
	EntityTimestamp *ra.ReadAccessFactsPlainEntityTimestampAttributes
	Symbol          *ra.ReadAccessFactsTaggedSymbol
	U64Array        *ra.ReadAccessFactsTaggedU64Array
	StringArray     *ra.ReadAccessFactsTaggedStringArray
	Bool            *ra.ReadAccessFactsTaggedBool
	U32Array        *ra.ReadAccessFactsTaggedU32Array
	BlobArray       *ra.ReadAccessFactsTaggedBlobArray
}

func newItemReader() *itemReader {
	return &itemReader{
		EntityId:        ra.NewReadAccessFactsPlainEntityIdAttributes(),
		EntityTimestamp: ra.NewReadAccessFactsPlainEntityTimestampAttributes(),
		Symbol:          ra.NewReadAccessFactsTaggedSymbol(),
		U64Array:        ra.NewReadAccessFactsTaggedU64Array(),
		StringArray:     ra.NewReadAccessFactsTaggedStringArray(),
		Bool:            ra.NewReadAccessFactsTaggedBool(),
		U32Array:        ra.NewReadAccessFactsTaggedU32Array(),
		BlobArray:       ra.NewReadAccessFactsTaggedBlobArray(),
	}
}

func (r *itemReader) loadFromRecord(rec arrow.Record) (err error) {
	err = r.EntityId.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("stevedoreitem: load EntityId: %w", err)
		return
	}
	err = r.EntityTimestamp.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("stevedoreitem: load EntityTimestamp: %w", err)
		return
	}
	err = r.Symbol.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("stevedoreitem: load Symbol: %w", err)
		return
	}
	err = r.U64Array.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("stevedoreitem: load U64Array: %w", err)
		return
	}
	err = r.StringArray.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("stevedoreitem: load StringArray: %w", err)
		return
	}
	err = r.Bool.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("stevedoreitem: load Bool: %w", err)
		return
	}
	err = r.U32Array.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("stevedoreitem: load U32Array: %w", err)
		return
	}
	err = r.BlobArray.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("stevedoreitem: load BlobArray: %w", err)
		return
	}
	return
}

func (r *itemReader) release() {
	if r == nil {
		return
	}
	if r.EntityId != nil {
		r.EntityId.Release()
	}
	if r.EntityTimestamp != nil {
		r.EntityTimestamp.Release()
	}
	if r.Symbol != nil {
		r.Symbol.Release()
	}
	if r.U64Array != nil {
		r.U64Array.Release()
	}
	if r.StringArray != nil {
		r.StringArray.Release()
	}
	if r.Bool != nil {
		r.Bool.Release()
	}
	if r.U32Array != nil {
		r.U32Array.Release()
	}
	if r.BlobArray != nil {
		r.BlobArray.Release()
	}
}

// Unmarshal appends one row to c per entity in rec, projecting
// the boxer.facts columns through factsschema/ra. Thin wrapper
// around ItemFillFromArrow — the per-row decode lives there.
func (c *ItemColumns) Unmarshal(rec arrow.Record) (err error) {
	r := newItemReader()
	defer r.release()
	err = r.loadFromRecord(rec)
	if err != nil {
		return
	}
	n := r.EntityId.Len()
	err = ItemFillFromArrow(
		c,
		n,
		r.EntityId.ValueId,
		r.EntityId.ValueNaturalKey,
		r.EntityTimestamp.ValueTs,
		r.Symbol.Attributes, r.Symbol.Memberships,
		r.U64Array.Attributes, r.U64Array.Memberships,
		r.StringArray.Attributes, r.StringArray.Memberships,
		r.Bool.Attributes, r.Bool.Memberships,
		r.U32Array.Attributes, r.U32Array.Memberships,
		r.BlobArray.Attributes, r.BlobArray.Memberships,
	)
	return
}

// --- buscodec.CodecI bridge. ---

// ItemCodec is the buscodec.CodecI bridge for Item. Encodes one row
// through dml_cbor; decodes via cborarrow.Convert + ra-Unmarshal +
// Row(0). Auto-registered in init() so callers using buscodec.Encode
// / Decode route through here instead of the CBOR fallback.
type ItemCodec struct{}

var _ buscodec.CodecI = (*ItemCodec)(nil)

// itemBusCodec is the package-local singleton wired into buscodec.
var itemBusCodec = &ItemCodec{}

func (inst *ItemCodec) Name() (n string) {
	n = "stevedoreItem-sparse-cbor"
	return
}

func (inst *ItemCodec) ContentType() (ct string) {
	ct = "application/x-runtime-facts+rb;kind=stevedoreItem"
	return
}

func (inst *ItemCodec) Encode(v any) (b []byte, err error) {
	var row Item
	switch x := v.(type) {
	case Item:
		row = x
	case *Item:
		if x == nil {
			err = eh.Errorf("stevedoreitem: Encode nil *Item")
			return
		}
		row = *x
	default:
		err = eh.Errorf("stevedoreitem: Encode requires Item or *Item, got %T", v)
		return
	}
	cols := &ItemColumns{}
	cols.Append(row)
	var buf bytes.Buffer
	err = cols.Marshal(&buf)
	if err != nil {
		err = eh.Errorf("stevedoreitem: Encode marshal: %w", err)
		return
	}
	b = buf.Bytes()
	return
}

func (inst *ItemCodec) Decode(b []byte, v any) (err error) {
	target, ok := v.(*Item)
	if !ok {
		err = eh.Errorf("stevedoreitem: Decode requires *Item, got %T", v)
		return
	}
	var arrowBuf bytes.Buffer
	err = cborarrow.Convert(bytes.NewReader(b), &arrowBuf)
	if err != nil {
		err = eh.Errorf("stevedoreitem: Decode cborarrow: %w", err)
		return
	}
	rd, err := ipc.NewReader(&arrowBuf)
	if err != nil {
		err = eh.Errorf("stevedoreitem: Decode ipc reader: %w", err)
		return
	}
	defer rd.Release()
	if !rd.Next() {
		err = eh.Errorf("stevedoreitem: Decode expected one Arrow record, got none")
		return
	}
	rec := rd.RecordBatch()
	defer rec.Release()
	cols := &ItemColumns{}
	err = cols.Unmarshal(rec)
	if err != nil {
		err = eh.Errorf("stevedoreitem: Decode unmarshal: %w", err)
		return
	}
	if cols.Len() != 1 {
		err = eb.Build().Int("got", cols.Len()).Errorf("stevedoreitem: Decode expected 1 row")
		return
	}
	*target = cols.Row(0)
	return
}
